verification_receipts.patch_excerpt:
diff --git a/scripts/test-executor-profiles.js b/scripts/test-executor-profiles.js
index 3178834..fda8479 100644
--- a/scripts/test-executor-profiles.js
+++ b/scripts/test-executor-profiles.js
@@ -156,7 +156,8 @@ const wrapperInput = {
 };
 const wrapper = profiles.createForkReceiptWrapper({ ...wrapperInput, signingKey });
 const publicKey = crypto.createPublicKey(signingKey);
-assert.equal(profiles.verifyForkReceiptWrapper(wrapper, { publicKey, expected: wrapperInput }).status, 'verified');
+const verification = profiles.verifyForkReceiptWrapper(wrapper, { publicKey, expected: wrapperInput });
+assert.equal(verification.status, 'verified');
 for (const field of ['fork_id', 'branch_id', 'contract_digest', 'executor_profile_digest', 'execution_receipt_digest', 'observation_digest']) {
   const tampered = copy(wrapper);
   tampered.receipt[field] = field.endsWith('digest') ? `sha256:${'c'.repeat(64)}` : `${tampered.receipt[field]}-tampered`;
@@ -185,4 +186,45 @@ for (const forbidden of ['signature', 'private', 'raw_output', 'env', 'command',
 }
 assert.equal(replay.model_status, 'unknown');

+// Regression: a missing observed model stays unknown in every telemetry shape --
+// including a model-less legacy profile, trusted telemetry that simply omits the
+// model, and a cryptographically verified receipt. None of those may be laundered
+// into a reported model match.
+const missingObservations = [
+  undefined, null, {}, { trusted: true }, { model: '', trusted: true },
+  { model: null, trusted: true }, { model: 42, trusted: true },
+];
+for (const profile of [local, legacy[0]]) {
+  for (const observation of missingObservations) {
+    const shape = JSON.stringify(observation) ?? 'undefined';
+    assert.deepEqual(profiles.evaluateModelProof(profile, observation), {
+      requested_model: profile.model === null ? 'default' : profile.model,
+      observed_model: null,
+      status: 'unknown',
+      reason_code: 'MODEL_OBSERVATION_MISSING',
+    }, `missing observed model must stay unknown for ${profile.profile_id} with ${shape}`);
+  }
+}
+
+const verifiedButUnobserved = profiles.missionControlExecutorState({
+  profile: local,
+  observation: { trusted: true, duration_ms: 1200, tokens: 900 },
+  wrapper,
+  verification,
+});
+assert.equal(verifiedButUnobserved.receipt_status, 'verified');
+assert.equal(verifiedButUnobserved.duration_status, 'known');
+assert.equal(verifiedButUnobserved.requested_model, local.model);
+assert.equal(verifiedButUnobserved.observed_model, null);
+assert.equal(verifiedButUnobserved.model_status, 'unknown');
+assert.equal(verifiedButUnobserved.model_reason_code, 'MODEL_OBSERVATION_MISSING');
+
+const verifiedButUnobservedReplay = profiles.publicExecutorReplay({
+  profile: local, observation: { trusted: true }, wrapper, verification,
+});
+assert.equal(verifiedButUnobservedReplay.receipt_status, 'verified');
+assert.equal(verifiedButUnobservedReplay.observed_model, null);
+assert.equal(verifiedButUnobservedReplay.model_status, 'unknown');
+assert.equal(verifiedButUnobservedReplay.model_reason_code, 'MODEL_OBSERVATION_MISSING');
+
 process.stdout.write('Executor profiles passed: strict profiles, canonical digests, literal invocations, bound receipts, and honest model proof.\n');
